extends RefCounted
func execute(scene_tree: SceneTree) -> Variant:
 scene_tree.root.disable_3d = true
 scene_tree.root.size = Vector2i(1280,900)
 var main = load("res://main.tscn").instantiate()
 main.prepare_initial_world = false
 main._settings_persistent = false
 main._force_touch = true
 scene_tree.root.add_child(main)
 main.set_process(false)
 main._router.capture_mouse = false
 main._router.gameplay_active = true
 var staged = main._native.debug_restart_at(Vector3(11.2,33.95,-125.3))
 for i in 180:
  main._process(1.0/90.0)
 var landing = main._native.get_landing_state()
 var state = main._story_guidance.sample(main._ctx, main._native.get_tick_index())
 scene_tree.current_scene.set_meta("stair_cue_main",main)
 return {"declared_initial_33m_stage_only":staged,"tick":main._native.get_tick_index(),"position":main._native.get_player_position(),"support":main._native.get_support_entity_id(),"grounded":main._native.is_player_grounded(),"firm":landing.checkpoint_footing_valid,"hands":landing.traversal_hand_constraint_count,"gravity":landing.player_gravity_factor,"deaths":main._native.get_death_count(),"cue":state.transmission_key,"radio":main._story_radio.readback(),"mission_hud_hidden":not main._story_presenter._objective.visible,"viewport_3d_disabled":scene_tree.root.disable_3d}

